import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-complete27-20261122',r=JSON.parse(fs.readFileSync(root+'/qualified-sites.json')),s=r.sites.find(s=>s.site==='molistar.com'),registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},pool,network,allowedDomains:registry.allowedDomains,profiles:{...JSON.parse(r.profilesText),[s.site]:s.profile},siteCooldown:false,maxWireRequests:8}),jobs=['https://molistar.com/wp-json/wp/v2/posts?per_page=5&_embed=author,wp:featuredmedia','https://molistar.com/wp-json/wp/v2/posts?slug=hien-mai-nguyen-vu-tiep-tuc-lam-giam-khao-hoa-hau-the-gioi-doanh-nhan-viet-nam-2026&_embed=author,wp:featuredmedia'],report={at:new Date().toISOString(),checks:[]};try{for(const url of jobs){const p=await driver.get('qc27-molistar-direct-api',url,s.config,[],{reviewFailed:true,taskRole:'publisher_dependency'}),o={url,error:p.error,statusCode:p.statusCode,proxyId:p.proxyId};if(!p.error&&p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));try{const data=JSON.parse(p.html);o.posts=(Array.isArray(data)?data:[data]).map(p=>({id:p.id,link:p.link,title:p.title?.rendered,date_gmt:p.date_gmt,type:p.type,status:p.status,bodyChars:p.content?.rendered?.length}));}catch{}}report.checks.push(o);console.log(JSON.stringify(o));}fs.writeFileSync(root+'/molistar-api-controls.json',JSON.stringify(report,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 "$root/molistar-api-controls.json" "$upload_dir/.qc27-complete-molistar-api.json"
